-- MARKER_E035_APPLY basic-sockets
-- ============================================================================
-- 20-sockets.sql (issue 155p, stage 3) — APPLY SOURCE
-- ============================================================================
-- Gem sockets on white gear sold in Azeroth's capitals and on blues from
-- vanilla's 5-person dungeons (design agreed with Ritz, 2026-09-25; quotes
-- in issue 155p):
--
--   gem tier    by item level: +4 gems below 30, +6 below 45, +8 from 45
--               (the smallest gems the client can describe; nothing below
--               item level 17 gets a socket, where a +4 gem outweighs a
--               green's whole stats)
--   whites      more sockets, small Stamina bonus: sockets and bonus sum
--               to about a same-level green's stats. At the capital sets'
--               item levels (17, 22, 27, 37, 50) the counts are the table
--               Ritz approved; elsewhere (weapons, shields) the same rule:
--               sockets = gems that fit the green's stats, bonus = the rest
--   blues       fewer sockets, big bonus of the item's own strongest stat:
--               fixed stats cut to about 80% of a same-level green's (an
--               empty-socket blue loses to the green), sockets and bonus
--               lift a filled one about 10% above its stock total; two
--               sockets only on chest, legs and two-handers with room for
--               both. Blues with random or no fixed stats keep stock form
--   colours     armor: red, yellow and blue as even as possible within each
--               white set (one armor type at one item level); a blue's
--               sockets take the gem colour of its two strongest stats
--               (red: Strength, Agility, attack and spell power; yellow:
--               Intellect and ratings; blue: Stamina, Spirit, resilience,
--               mana every 5 seconds). Weapons: colourless (prismatic)
--               sockets, no bonus
--   honesty     bonuses are enchantments whose whole effect is one stat
--               and whose text says exactly that (generated list)
--
-- "A same-level green's stats": the average total of fixed-stat greens in
-- the item's 5-level band and slot size (big: chest, legs, two-handers;
-- middle: head, shoulders, hands, feet, waist, one-handers, off-hands;
-- small: wrist, neck, rings, back, ranged).
-- Items that already have sockets are left alone. Every changed column is
-- saved (basic_155p_socket_backup); each apply first restores them.
-- Database: acore_world_basic. Applied by E035. Durability of white gear
-- is a separate patch.
-- ============================================================================

-- ---- 0. put back what an earlier apply changed -----------------------------------------
CREATE TABLE IF NOT EXISTS `basic_155p_socket_backup` (PRIMARY KEY (`entry`))
ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='issue 155p: stock sockets and stats of every item stage 3 socketed, for the revert'
SELECT `entry`, `socketColor_1`, `socketColor_2`, `socketColor_3`, `socketBonus`,
       `stat_value1`, `stat_value2`, `stat_value3`, `stat_value4`, `stat_value5`,
       `stat_value6`, `stat_value7`, `stat_value8`, `stat_value9`, `stat_value10`
FROM `item_template` LIMIT 0;
UPDATE `item_template` i JOIN `basic_155p_socket_backup` b ON b.`entry` = i.`entry` SET
  i.`socketColor_1` = b.`socketColor_1`, i.`socketColor_2` = b.`socketColor_2`, i.`socketColor_3` = b.`socketColor_3`,
  i.`socketBonus` = b.`socketBonus`,
  i.`stat_value1` = b.`stat_value1`, i.`stat_value2` = b.`stat_value2`, i.`stat_value3` = b.`stat_value3`,
  i.`stat_value4` = b.`stat_value4`, i.`stat_value5` = b.`stat_value5`, i.`stat_value6` = b.`stat_value6`,
  i.`stat_value7` = b.`stat_value7`, i.`stat_value8` = b.`stat_value8`, i.`stat_value9` = b.`stat_value9`,
  i.`stat_value10` = b.`stat_value10`;
DELETE FROM `basic_155p_socket_backup`;

