SELECT FLOOR(i.`ItemLevel` / 5) * 5, s.`size`,
       AVG(i.`stat_value1` + i.`stat_value2` + i.`stat_value3` + i.`stat_value4` + i.`stat_value5`
         + i.`stat_value6` + i.`stat_value7` + i.`stat_value8` + i.`stat_value9` + i.`stat_value10`)
FROM `item_template` i JOIN `tmp_155p_slot` s ON s.`inv` = i.`InventoryType`
WHERE i.`Quality` = 2 AND i.`class` IN (2, 4) AND i.`RandomProperty` = 0 AND i.`RandomSuffix` = 0
  AND i.`ItemLevel` BETWEEN 15 AND 69
  AND (i.`stat_value1` + i.`stat_value2` + i.`stat_value3` + i.`stat_value4` + i.`stat_value5`
     + i.`stat_value6` + i.`stat_value7` + i.`stat_value8` + i.`stat_value9` + i.`stat_value10`) > 0
GROUP BY FLOOR(i.`ItemLevel` / 5) * 5, s.`size`;

-- ---- 3. which items --------------------------------------------------------------------------
DROP TABLE IF EXISTS `tmp_155p_items`;
CREATE TABLE `tmp_155p_items` (
  `entry` int unsigned NOT NULL, `kind` char(1) NOT NULL COMMENT 'w white, b blue',
  `weapon` tinyint unsigned NOT NULL, `size` tinyint unsigned NOT NULL, `lvl` smallint unsigned NOT NULL,
  `setkey` varchar(24) NOT NULL, `inv` tinyint unsigned NOT NULL,
  `gem` tinyint unsigned NOT NULL, `g` float NOT NULL, `total` int NOT NULL DEFAULT 0,
  `sockets` tinyint unsigned NOT NULL DEFAULT 0, `bonus` smallint unsigned NOT NULL DEFAULT 0,
  `keep` float NOT NULL DEFAULT 1, `top1` tinyint unsigned NOT NULL DEFAULT 0, `top2` tinyint unsigned NOT NULL DEFAULT 0,
  PRIMARY KEY (`entry`));
-- whites sold by vendors standing in the capitals (not fishing poles,
-- miscellaneous or thrown weapons)
INSERT IGNORE INTO `tmp_155p_items` (`entry`, `kind`, `weapon`, `size`, `lvl`, `setkey`, `inv`, `gem`, `g`)
SELECT DISTINCT i.`entry`, 'w', i.`class` = 2, s.`size`, i.`ItemLevel`, CONCAT(i.`class`, '-', i.`subclass`, '-', i.`ItemLevel`), i.`InventoryType`,
       IF(i.`ItemLevel` < 30, 4, IF(i.`ItemLevel` < 45, 6, 8)), gr.`g`
FROM `tmp_155p_capitals` k
JOIN `creature` c ON c.`map` = k.`map` AND c.`position_x` BETWEEN k.`x0` AND k.`x1` AND c.`position_y` BETWEEN k.`y0` AND k.`y1`
JOIN `npc_vendor` v ON v.`entry` = c.`id`
JOIN `item_template` i ON i.`entry` = v.`item`
JOIN `tmp_155p_slot` s ON s.`inv` = i.`InventoryType`
JOIN `tmp_155p_green` gr ON gr.`band` = FLOOR(i.`ItemLevel` / 5) * 5 AND gr.`size` = s.`size`
WHERE i.`Quality` = 1 AND i.`class` IN (2, 4) AND i.`ItemLevel` BETWEEN 17 AND 63
  AND NOT (i.`class` = 2 AND i.`subclass` IN (14, 16, 20))
  AND i.`socketColor_1` = 0 AND i.`socketColor_2` = 0 AND i.`socketColor_3` = 0;

-- blues from vanilla's 5-person dungeons: their creatures' and chests' loot,
-- references followed three levels deep
DROP TABLE IF EXISTS `tmp_155p_src`;
CREATE TABLE `tmp_155p_src` (`kind` char(1) NOT NULL, `id` int unsigned NOT NULL, PRIMARY KEY (`kind`, `id`));
INSERT IGNORE INTO `tmp_155p_src` SELECT 'c', t.`lootid` FROM `creature` c JOIN `creature_template` t ON t.`entry` = c.`id`
WHERE c.`map` IN (SELECT `map_id` FROM `tmp_155p_dungeons`) AND t.`lootid` <> 0;
INSERT IGNORE INTO `tmp_155p_src` SELECT 'g', g.`Data1` FROM `gameobject` o JOIN `gameobject_template` g ON g.`entry` = o.`id`
WHERE o.`map` IN (SELECT `map_id` FROM `tmp_155p_dungeons`) AND g.`type` = 3 AND g.`Data1` <> 0;
INSERT IGNORE INTO `tmp_155p_src` SELECT 'r', l.`Reference` FROM `creature_loot_template` l JOIN `tmp_155p_src` k ON k.`kind` = 'c' AND k.`id` = l.`Entry` WHERE l.`Reference` <> 0;
INSERT IGNORE INTO `tmp_155p_src` SELECT 'r', l.`Reference` FROM `gameobject_loot_template` l JOIN `tmp_155p_src` k ON k.`kind` = 'g' AND k.`id` = l.`Entry` WHERE l.`Reference` <> 0;
DROP TABLE IF EXISTS `tmp_155p_step`;
CREATE TABLE `tmp_155p_step` (`id` int unsigned NOT NULL, PRIMARY KEY (`id`));
INSERT IGNORE INTO `tmp_155p_step` SELECT l.`Reference` FROM `reference_loot_template` l JOIN `tmp_155p_src` k ON k.`kind` = 'r' AND k.`id` = l.`Entry` WHERE l.`Reference` <> 0;
INSERT IGNORE INTO `tmp_155p_src` SELECT 'r', `id` FROM `tmp_155p_step`;
DELETE FROM `tmp_155p_step`;
INSERT IGNORE INTO `tmp_155p_step` SELECT l.`Reference` FROM `reference_loot_template` l JOIN `tmp_155p_src` k ON k.`kind` = 'r' AND k.`id` = l.`Entry` WHERE l.`Reference` <> 0;
INSERT IGNORE INTO `tmp_155p_src` SELECT 'r', `id` FROM `tmp_155p_step`;
DROP TABLE IF EXISTS `tmp_155p_loot`;
CREATE TABLE `tmp_155p_loot` (`item` int unsigned NOT NULL, PRIMARY KEY (`item`));
INSERT IGNORE INTO `tmp_155p_loot` SELECT l.`Item` FROM `creature_loot_template` l   JOIN `tmp_155p_src` k ON k.`kind` = 'c' AND k.`id` = l.`Entry` WHERE l.`Reference` = 0;
INSERT IGNORE INTO `tmp_155p_loot` SELECT l.`Item` FROM `gameobject_loot_template` l JOIN `tmp_155p_src` k ON k.`kind` = 'g' AND k.`id` = l.`Entry` WHERE l.`Reference` = 0;
INSERT IGNORE INTO `tmp_155p_loot` SELECT l.`Item` FROM `reference_loot_template` l  JOIN `tmp_155p_src` k ON k.`kind` = 'r' AND k.`id` = l.`Entry` WHERE l.`Reference` = 0;

INSERT IGNORE INTO `tmp_155p_items` (`entry`, `kind`, `weapon`, `size`, `lvl`, `setkey`, `inv`, `gem`, `g`, `total`)
SELECT i.`entry`, 'b', i.`class` = 2, s.`size`, i.`ItemLevel`, CONCAT('blue-', i.`entry`), i.`InventoryType`,
       IF(i.`ItemLevel` < 30, 4, IF(i.`ItemLevel` < 45, 6, 8)), gr.`g`,
       GREATEST(i.`stat_value1`, 0) + GREATEST(i.`stat_value2`, 0) + GREATEST(i.`stat_value3`, 0) + GREATEST(i.`stat_value4`, 0)
     + GREATEST(i.`stat_value5`, 0) + GREATEST(i.`stat_value6`, 0) + GREATEST(i.`stat_value7`, 0) + GREATEST(i.`stat_value8`, 0)
     + GREATEST(i.`stat_value9`, 0) + GREATEST(i.`stat_value10`, 0)
FROM `tmp_155p_loot` l
JOIN `item_template` i ON i.`entry` = l.`item`
JOIN `tmp_155p_slot` s ON s.`inv` = i.`InventoryType`
JOIN `tmp_155p_green` gr ON gr.`band` = FLOOR(i.`ItemLevel` / 5) * 5 AND gr.`size` = s.`size`
WHERE i.`Quality` = 3 AND i.`class` IN (2, 4) AND i.`ItemLevel` BETWEEN 17 AND 63
  AND i.`RandomProperty` = 0 AND i.`RandomSuffix` = 0
  AND i.`socketColor_1` = 0 AND i.`socketColor_2` = 0 AND i.`socketColor_3` = 0;
DELETE FROM `tmp_155p_items` WHERE `kind` = 'b' AND `total` <= 0;     -- nothing to drain

-- ---- 4. sockets, bonus, and what the blues keep ----------------------------------------------
-- whites: Ritz's approved table at the capital sets' item levels, the same
-- rule elsewhere; weapons fill with gems only
DROP TABLE IF EXISTS `tmp_155p_table`;
CREATE TABLE `tmp_155p_table` (`lvl` smallint unsigned NOT NULL, `size` tinyint unsigned NOT NULL, `sockets` tinyint unsigned NOT NULL, `bonus` tinyint unsigned NOT NULL, PRIMARY KEY (`lvl`, `size`));
INSERT INTO `tmp_155p_table` VALUES
  (17,1,1,2),(17,2,1,1),(17,3,1,0),
  (22,1,2,1),(22,2,1,3),(22,3,1,1),
  (27,1,3,0),(27,2,2,2),(27,3,1,2),
  (37,1,3,0),(37,2,2,3),(37,3,1,4),
  (50,1,3,2),(50,2,2,5),(50,3,2,0);
UPDATE `tmp_155p_items` t LEFT JOIN `tmp_155p_table` a ON a.`lvl` = t.`lvl` AND a.`size` = t.`size` SET
  t.`sockets` = IF(t.`weapon`, LEAST(3, GREATEST(1, ROUND(t.`g` / t.`gem`))),
                  COALESCE(a.`sockets`, LEAST(3, GREATEST(1, FLOOR(t.`g` / t.`gem` + 0.25))))),
  t.`bonus`   = IF(t.`weapon`, 0, COALESCE(a.`bonus`, GREATEST(0, ROUND(t.`g` - GREATEST(1, FLOOR(t.`g` / t.`gem` + 0.25)) * t.`gem`))))
WHERE t.`kind` = 'w';
-- blues: keep = the share of fixed stats left (80% of a green, never more
-- than stock); room = what gems and bonus make up, to 110% of stock
UPDATE `tmp_155p_items` SET `keep` = LEAST(1, 0.8 * `g` / `total`) WHERE `kind` = 'b';
UPDATE `tmp_155p_items` SET
  `sockets` = IF(`weapon`, LEAST(3, GREATEST(1, ROUND((1.1 * `total` - `keep` * `total`) / `gem`))),
                 1 + IF(`size` = 1 AND (1.1 * `total` - `keep` * `total`) >= 2.5 * `gem`, 1, 0)),
  `bonus`   = 0
WHERE `kind` = 'b';
UPDATE `tmp_155p_items` SET `bonus` = GREATEST(0, ROUND(1.1 * `total` - `keep` * `total` - `sockets` * `gem`))
WHERE `kind` = 'b' AND NOT `weapon`;
-- a blue with too little room for even one gem keeps its stock form
DELETE FROM `tmp_155p_items` WHERE `kind` = 'b' AND (1.1 * `total` - `keep` * `total`) < 0.75 * `gem`;

-- the blues' two strongest stats (by value), for colours and the bonus stat
DROP TABLE IF EXISTS `tmp_155p_stats`;
CREATE TABLE `tmp_155p_stats` (`entry` int unsigned NOT NULL, `stat` tinyint unsigned NOT NULL, `val` int NOT NULL, KEY (`entry`));
INSERT INTO `tmp_155p_stats`
SELECT i.`entry`, x.`stat`, x.`val` FROM `tmp_155p_items` t JOIN `item_template` i ON i.`entry` = t.`entry`
JOIN LATERAL (SELECT i.`stat_type1` AS `stat`, i.`stat_value1` AS `val` UNION ALL SELECT i.`stat_type2`, i.`stat_value2`
  UNION ALL SELECT i.`stat_type3`, i.`stat_value3` UNION ALL SELECT i.`stat_type4`, i.`stat_value4`
  UNION ALL SELECT i.`stat_type5`, i.`stat_value5` UNION ALL SELECT i.`stat_type6`, i.`stat_value6`
  UNION ALL SELECT i.`stat_type7`, i.`stat_value7` UNION ALL SELECT i.`stat_type8`, i.`stat_value8`
  UNION ALL SELECT i.`stat_type9`, i.`stat_value9` UNION ALL SELECT i.`stat_type10`, i.`stat_value10`) x
WHERE t.`kind` = 'b' AND x.`val` > 0;
DROP TABLE IF EXISTS `tmp_155p_ranked`;
CREATE TABLE `tmp_155p_ranked` SELECT `entry`, `stat`, ROW_NUMBER() OVER (PARTITION BY `entry` ORDER BY `val` DESC, `stat`) AS `r` FROM `tmp_155p_stats`;
UPDATE `tmp_155p_items` t JOIN `tmp_155p_ranked` r ON r.`entry` = t.`entry` AND r.`r` = 1 SET t.`top1` = r.`stat`;
UPDATE `tmp_155p_items` t JOIN `tmp_155p_ranked` r ON r.`entry` = t.`entry` AND r.`r` = 2 SET t.`top2` = r.`stat`;
UPDATE `tmp_155p_items` SET `top2` = `top1` WHERE `kind` = 'b' AND `top2` = 0;

-- ---- 5. colours -------------------------------------------------------------------------------
-- socket colours: 2 red, 4 yellow, 8 blue, 14 prismatic. A stat's gem colour:
-- red Strength (4), Agility (3), attack power (38, 39), spell power (45) and
-- the old spell damage/healing (41, 42); blue Stamina (7), Spirit (6),
-- resilience (35), mana (43) and health (46) regeneration; yellow the rest.
DROP TABLE IF EXISTS `tmp_155p_sockets`;
CREATE TABLE `tmp_155p_sockets` (`entry` int unsigned NOT NULL, `n` tinyint unsigned NOT NULL, `color` tinyint unsigned NOT NULL DEFAULT 0, PRIMARY KEY (`entry`, `n`));
INSERT INTO `tmp_155p_sockets` (`entry`, `n`)
SELECT t.`entry`, k.`n` FROM `tmp_155p_items` t JOIN (SELECT 1 AS `n` UNION ALL SELECT 2 UNION ALL SELECT 3) k ON k.`n` <= t.`sockets`;
-- whites' armor: red, yellow, blue in turn across each set, slot by slot
DROP TABLE IF EXISTS `tmp_155p_turn`;
CREATE TABLE `tmp_155p_turn` SELECT s.`entry`, s.`n`,
  ROW_NUMBER() OVER (PARTITION BY t.`setkey` ORDER BY t.`inv`, t.`entry`, s.`n`) - 1 AS `k`
FROM `tmp_155p_sockets` s JOIN `tmp_155p_items` t ON t.`entry` = s.`entry` WHERE t.`kind` = 'w' AND NOT t.`weapon`;
UPDATE `tmp_155p_sockets` s JOIN `tmp_155p_turn` u ON u.`entry` = s.`entry` AND u.`n` = s.`n`
SET s.`color` = ELT(u.`k` % 3 + 1, 2, 4, 8);
-- blues' armor: first socket its strongest stat's colour, second its next
UPDATE `tmp_155p_sockets` s JOIN `tmp_155p_items` t ON t.`entry` = s.`entry`
SET s.`color` = CASE WHEN (IF(s.`n` = 1, t.`top1`, t.`top2`)) IN (3, 4, 38, 39, 41, 42, 45) THEN 2
                     WHEN (IF(s.`n` = 1, t.`top1`, t.`top2`)) IN (6, 7, 35, 43, 46) THEN 8 ELSE 4 END
WHERE t.`kind` = 'b' AND NOT t.`weapon`;
UPDATE `tmp_155p_sockets` s JOIN `tmp_155p_items` t ON t.`entry` = s.`entry` SET s.`color` = 14 WHERE t.`weapon`;

-- ---- 6. the bonus enchantment ----------------------------------------------------------------
-- whites Stamina, blues their strongest stat; the honest enchantment of that
-- stat at the size, or the largest one below it
DROP TABLE IF EXISTS `tmp_155p_pick`;
CREATE TABLE `tmp_155p_pick` (`entry` int unsigned NOT NULL, `enchant` int unsigned NULL, PRIMARY KEY (`entry`));
INSERT INTO `tmp_155p_pick`
SELECT t.`entry`, (SELECT b.`enchant` FROM `tmp_155p_bonus` b
                   WHERE b.`stat` = IF(t.`kind` = 'w', 7, t.`top1`) AND b.`amount` <= t.`bonus`
                   ORDER BY b.`amount` DESC, b.`enchant` LIMIT 1)
FROM `tmp_155p_items` t WHERE t.`bonus` > 0;
-- (no honest enchantment of that stat small enough: no bonus)
DELETE FROM `tmp_155p_pick` WHERE `enchant` IS NULL;

-- ---- 7. save, then write ----------------------------------------------------------------------
INSERT INTO `basic_155p_socket_backup`
SELECT i.`entry`, i.`socketColor_1`, i.`socketColor_2`, i.`socketColor_3`, i.`socketBonus`,
       i.`stat_value1`, i.`stat_value2`, i.`stat_value3`, i.`stat_value4`, i.`stat_value5`,
       i.`stat_value6`, i.`stat_value7`, i.`stat_value8`, i.`stat_value9`, i.`stat_value10`
FROM `item_template` i JOIN `tmp_155p_items` t ON t.`entry` = i.`entry`;
UPDATE `item_template` i JOIN `tmp_155p_items` t ON t.`entry` = i.`entry` SET
  i.`socketColor_1` = COALESCE((SELECT s.`color` FROM `tmp_155p_sockets` s WHERE s.`entry` = t.`entry` AND s.`n` = 1), 0),
  i.`socketColor_2` = COALESCE((SELECT s.`color` FROM `tmp_155p_sockets` s WHERE s.`entry` = t.`entry` AND s.`n` = 2), 0),
  i.`socketColor_3` = COALESCE((SELECT s.`color` FROM `tmp_155p_sockets` s WHERE s.`entry` = t.`entry` AND s.`n` = 3), 0),
  i.`socketBonus`   = COALESCE((SELECT p.`enchant` FROM `tmp_155p_pick` p WHERE p.`entry` = t.`entry`), 0);
-- the blues' fixed stats shrink to what they keep (a stat never to zero)
UPDATE `item_template` i JOIN `tmp_155p_items` t ON t.`entry` = i.`entry` SET
  i.`stat_value1`  = IF(i.`stat_value1`  > 0, GREATEST(1, ROUND(i.`stat_value1`  * t.`keep`)), i.`stat_value1`),
  i.`stat_value2`  = IF(i.`stat_value2`  > 0, GREATEST(1, ROUND(i.`stat_value2`  * t.`keep`)), i.`stat_value2`),
  i.`stat_value3`  = IF(i.`stat_value3`  > 0, GREATEST(1, ROUND(i.`stat_value3`  * t.`keep`)), i.`stat_value3`),
  i.`stat_value4`  = IF(i.`stat_value4`  > 0, GREATEST(1, ROUND(i.`stat_value4`  * t.`keep`)), i.`stat_value4`),
  i.`stat_value5`  = IF(i.`stat_value5`  > 0, GREATEST(1, ROUND(i.`stat_value5`  * t.`keep`)), i.`stat_value5`),
  i.`stat_value6`  = IF(i.`stat_value6`  > 0, GREATEST(1, ROUND(i.`stat_value6`  * t.`keep`)), i.`stat_value6`),
  i.`stat_value7`  = IF(i.`stat_value7`  > 0, GREATEST(1, ROUND(i.`stat_value7`  * t.`keep`)), i.`stat_value7`),
  i.`stat_value8`  = IF(i.`stat_value8`  > 0, GREATEST(1, ROUND(i.`stat_value8`  * t.`keep`)), i.`stat_value8`),
  i.`stat_value9`  = IF(i.`stat_value9`  > 0, GREATEST(1, ROUND(i.`stat_value9`  * t.`keep`)), i.`stat_value9`),
  i.`stat_value10` = IF(i.`stat_value10` > 0, GREATEST(1, ROUND(i.`stat_value10` * t.`keep`)), i.`stat_value10`)
WHERE t.`kind` = 'b';

-- kept for the post-install checks
DROP TABLE IF EXISTS `basic_155p_socketed`;
CREATE TABLE `basic_155p_socketed` ENGINE=InnoDB COMMENT='issue 155p: every item stage 3 socketed, with its plan (read by scripts/validate-basic-state)'
SELECT `entry`, `kind`, `weapon`, `size`, `lvl`, `setkey`, `gem`, `g`, `total`, `sockets`, `bonus`, `keep` FROM `tmp_155p_items`;

DROP TABLE `tmp_155p_pick`;
DROP TABLE `tmp_155p_turn`;
DROP TABLE `tmp_155p_sockets`;
DROP TABLE `tmp_155p_ranked`;
DROP TABLE `tmp_155p_stats`;
DROP TABLE `tmp_155p_table`;
DROP TABLE `tmp_155p_loot`;
DROP TABLE `tmp_155p_step`;
DROP TABLE `tmp_155p_src`;
DROP TABLE `tmp_155p_items`;
DROP TABLE `tmp_155p_green`;
DROP TABLE `tmp_155p_slot`;
DROP TABLE `tmp_155p_capitals`;
DROP TABLE `tmp_155p_dungeons`;
DROP TABLE `tmp_155p_bonus`;

